"use strict";
import { Contract } from "@ethersproject/contracts";
export class GaugeStakingService {
  constructor(provider) {
    this.provider = provider;
  }
  /**
   * Check if a tokenId is staked by a user in a specific gauge
   */
  async checkStaking(gaugeAddress, tokenId, userAddress) {
    try {
      const gaugeABI = [
        {
          inputs: [{ name: "user", type: "address" }],
          name: "stakedLength",
          outputs: [{ name: "", type: "uint256" }],
          stateMutability: "view",
          type: "function"
        },
        {
          inputs: [{ name: "user", type: "address" }, { name: "index", type: "uint256" }],
          name: "stakedByIndex",
          outputs: [{ name: "", type: "uint256" }],
          stateMutability: "view",
          type: "function"
        }
      ];
      const gaugeContract = new Contract(gaugeAddress, gaugeABI, this.provider);
      const stakedLength = await gaugeContract.stakedLength(userAddress);
      const stakedCount = parseInt(stakedLength.toString());
      if (stakedCount === 0) {
        return { isStaked: false };
      }
      for (let i = 0; i < stakedCount; i++) {
        const stakedTokenId = await gaugeContract.stakedByIndex(userAddress, i);
        const stakedTokenIdStr = stakedTokenId.toString();
        if (stakedTokenIdStr === tokenId) {
          console.log(`\u2705 [GAUGE STAKING] Found matching tokenId ${tokenId} at index ${i}`);
          return {
            isStaked: true,
            gaugeAddress
          };
        }
      }
      return { isStaked: false };
    } catch (error) {
      console.error(`Error checking staking in gauge ${gaugeAddress}:`, error);
      return { isStaked: false };
    }
  }
}
