"use strict";
import { CurrencyAmount, Token } from "@uniswap/sdk-core";
import { Pool as V3Pool } from "@uniswap/v3-sdk";
import JSBI from "jsbi";
export class V3PositionCalculationService {
  constructor(positionManager, chainId) {
    this.positionManager = positionManager;
    this.chainId = chainId;
  }
  /**
   * Calculate position amounts using decreaseLiquidity simulation
   */
  async calculateAmounts(tokenId, positionData, poolData, owner) {
    if (!poolData) {
      return this.createFallbackAmounts(positionData);
    }
    const token0 = new Token(
      this.chainId,
      positionData[2],
      parseInt(poolData.token0.decimals),
      poolData.token0.symbol,
      poolData.token0.name
    );
    const token1 = new Token(
      this.chainId,
      positionData[3],
      parseInt(poolData.token1.decimals),
      poolData.token1.symbol,
      poolData.token1.name
    );
    const positionLiquidity = JSBI.BigInt(positionData[7].toString());
    if (JSBI.equal(positionLiquidity, JSBI.BigInt(0))) {
      return {
        currency0Amount: CurrencyAmount.fromRawAmount(token0, 0),
        currency1Amount: CurrencyAmount.fromRawAmount(token1, 0)
      };
    }
    const feeAmount = this.tickSpacingToFee(parseInt(poolData.tickSpacing));
    const pool = new V3Pool(
      token0,
      token1,
      feeAmount,
      JSBI.BigInt(poolData.sqrtPrice),
      JSBI.BigInt(poolData.liquidity),
      parseInt(poolData.tick)
    );
    try {
      const decreaseParams = {
        tokenId,
        liquidity: positionData[7],
        amount0Min: 0,
        amount1Min: 0,
        deadline: Math.floor(Date.now() / 1e3) + 3600
      };
      const result = await this.positionManager.callStatic.decreaseLiquidity(decreaseParams, { from: owner });
      return {
        currency0Amount: CurrencyAmount.fromRawAmount(token0, result.amount0.toString()),
        currency1Amount: CurrencyAmount.fromRawAmount(token1, result.amount1.toString()),
        pool
      };
    } catch (simulationError) {
      console.error("V3 amount calculation failed:", simulationError);
      return {
        currency0Amount: CurrencyAmount.fromRawAmount(token0, 0),
        currency1Amount: CurrencyAmount.fromRawAmount(token1, 0),
        pool
      };
    }
  }
  /**
   * Create fallback amounts when no pool data is available
   */
  createFallbackAmounts(positionData) {
    const token0 = new Token(this.chainId, positionData[2], 18, "TOKEN0", "Token 0");
    const token1 = new Token(this.chainId, positionData[3], 18, "TOKEN1", "Token 1");
    return {
      currency0Amount: CurrencyAmount.fromRawAmount(token0, 0),
      currency1Amount: CurrencyAmount.fromRawAmount(token1, 0)
    };
  }
  /**
   * Convert tick spacing to fee amount (Abstract DEX mapping)
   */
  tickSpacingToFee(tickSpacing) {
    const feeMap = {
      1: 100,
      50: 500,
      100: 500,
      200: 3e3,
      2e3: 1e4
    };
    return feeMap[tickSpacing] || 3e3;
  }
}
