"use strict";
import { useQuery } from "@tanstack/react-query";
import { BigNumber } from "@ethersproject/bignumber";
import { useAccount } from "hooks/useAccount";
import { useEthersProvider } from "hooks/useEthersProvider";
import { getAbstractContracts } from "uniswap/src/constants/abstractContracts";
import { PositionStatus } from "@uniswap/client-pools/dist/pools/v1/types_pb";
import { getContract } from "utilities/src/contracts/getContract";
import NonfungiblePositionManagerJson from "@uniswap/v3-periphery/artifacts/contracts/NonfungiblePositionManager.sol/NonfungiblePositionManager.json";
import { NFTOwnershipService } from "./services/NFTOwnershipService";
import { GaugeStakingService } from "./services/GaugeStakingService";
import { V3PoolDataService } from "./services/V3PoolDataService";
import { V3PositionCalculationService } from "./services/V3PositionCalculationService";
import { V3FeeCalculationService } from "./services/V3FeeCalculationService";
const { abi: NFTPositionManagerABI } = NonfungiblePositionManagerJson;
export function useAbstractPosition(tokenId, chainId) {
  const account = useAccount();
  const provider = useEthersProvider({ chainId });
  const contracts = getAbstractContracts(chainId);
  return useQuery({
    queryKey: ["abstract-position-orchestrated", tokenId, chainId, account.address],
    queryFn: async () => {
      if (!tokenId || !account.address || !provider || !contracts?.nonfungiblePositionManager) {
        return null;
      }
      try {
        console.log(`\u{1F3AD} [POSITION ORCHESTRATOR] Fetching position ${tokenId} for user ${account.address}`);
        const ownershipService = new NFTOwnershipService(contracts.nonfungiblePositionManager, provider);
        const stakingService = new GaugeStakingService(provider);
        const poolDataService = new V3PoolDataService();
        const positionManager = getContract(
          contracts.nonfungiblePositionManager,
          NFTPositionManagerABI,
          provider
        );
        const calculationService = new V3PositionCalculationService(positionManager, chainId);
        const feeService = new V3FeeCalculationService(positionManager, provider);
        const ownershipResult = await ownershipService.checkOwnership(tokenId);
        if (!ownershipResult.exists) {
          console.log(`\u274C [POSITION ORCHESTRATOR] Position ${tokenId} does not exist`);
          return null;
        }
        const { owner, positionData } = ownershipResult;
        const isOwnedByUser = owner.toLowerCase() === account.address.toLowerCase();
        let isStaked = false;
        let gaugeAddress;
        if (!isOwnedByUser) {
          console.log(`\u{1F50D} [POSITION ORCHESTRATOR] Position owned by ${owner}, checking if it's a gauge`);
          const stakingResult = await stakingService.checkStaking(owner, tokenId, account.address);
          if (!stakingResult.isStaked) {
            console.log(`\u274C [POSITION ORCHESTRATOR] Position not owned by user and not staked by user`);
            return null;
          }
          isStaked = true;
          gaugeAddress = stakingResult.gaugeAddress;
          console.log(`\u2705 [POSITION ORCHESTRATOR] Position is staked in gauge ${gaugeAddress}`);
        }
        const positionTickSpacing = positionData[4];
        const poolData = await poolDataService.fetchPoolData(
          positionData[2],
          // token0
          positionData[3],
          // token1
          positionTickSpacing
        );
        const { currency0Amount, currency1Amount, pool } = await calculationService.calculateAmounts(
          tokenId,
          positionData,
          poolData,
          owner
          // Use actual owner (user or gauge)
        );
        const { token0UncollectedFees, token1UncollectedFees } = await feeService.calculateFees(
          tokenId,
          positionData,
          poolData,
          owner
          // Use actual owner (user or gauge)
        );
        const status = getPositionStatus(
          parseInt(poolData?.tick || "0"),
          positionData[5],
          // tickLower
          positionData[6],
          // tickUpper
          !BigNumber.from(positionData[7]).eq(0)
          // hasLiquidity
        );
        console.log(`\u2705 [POSITION ORCHESTRATOR] Successfully processed position ${tokenId}`, {
          isStaked,
          gaugeAddress,
          status,
          owner,
          hasPoolData: !!poolData
        });
        return {
          position: {
            position: {
              case: "v3Position",
              value: {
                tokenId,
                token0: {
                  address: positionData[2],
                  chainId,
                  decimals: parseInt(poolData?.token0.decimals || "18"),
                  symbol: poolData?.token0.symbol || "TOKEN0",
                  name: poolData?.token0.name || "Token 0"
                },
                token1: {
                  address: positionData[3],
                  chainId,
                  decimals: parseInt(poolData?.token1.decimals || "18"),
                  symbol: poolData?.token1.symbol || "TOKEN1",
                  name: poolData?.token1.name || "Token 1"
                },
                feeTier: poolData ? tickSpacingToFee(parseInt(poolData.tickSpacing)).toString() : "3000",
                poolId: poolData?.id || "",
                tickSpacing: positionTickSpacing.toString(),
                poolInfo: poolData ? {
                  fee: tickSpacingToFee(parseInt(poolData.tickSpacing)),
                  sqrtPriceX96: poolData.sqrtPrice,
                  liquidity: poolData.liquidity,
                  tick: parseInt(poolData.tick),
                  tickSpacing: parseInt(poolData.tickSpacing),
                  token0Price: pool?.token0Price,
                  token1Price: pool?.token1Price
                } : void 0,
                liquidity: positionData[7].toString(),
                tickLower: positionData[5].toString(),
                tickUpper: positionData[6].toString(),
                amount0: currency0Amount?.quotient.toString() || "0",
                amount1: currency1Amount?.quotient.toString() || "0",
                token0UncollectedFees,
                token1UncollectedFees,
                apr: 0,
                owner,
                currentPrice: poolData?.sqrtPrice || "0",
                currentLiquidity: poolData?.liquidity || "0",
                currentTick: poolData?.tick || "0",
                poolId: poolData?.id || ""
              }
            }
          },
          status,
          chainId,
          isHidden: false,
          isStaked,
          gaugeAddress
        };
      } catch (error) {
        console.error(`\u274C [POSITION ORCHESTRATOR] Error fetching position ${tokenId}:`, error);
        return null;
      }
    },
    enabled: !!tokenId && !!account.address && !!provider && !!contracts?.nonfungiblePositionManager,
    refetchInterval: 3e4
    // Refetch every 30 seconds
  });
}
function getPositionStatus(currentTick, tickLower, tickUpper, hasLiquidity) {
  if (!hasLiquidity) {
    return PositionStatus.CLOSED;
  }
  if (currentTick >= tickLower && currentTick <= tickUpper) {
    return PositionStatus.IN_RANGE;
  } else {
    return PositionStatus.OUT_OF_RANGE;
  }
}
function tickSpacingToFee(tickSpacing) {
  const feeMap = {
    1: 100,
    50: 500,
    100: 500,
    200: 3e3,
    2e3: 1e4
  };
  return feeMap[tickSpacing] || 3e3;
}
