"use strict";
import { Contract } from "@ethersproject/contracts";
import { TickLibrary } from "../../uniswap-deps/v3-sdk/src/utils/tickLibrary";
import { PositionLibrary } from "../../uniswap-deps/v3-sdk/src/utils/position";
import JSBI from "jsbi";
export class V3FeeCalculationService {
  constructor(positionManager, provider) {
    this.positionManager = positionManager;
    this.provider = provider;
    this.multicall = new Contract("0xcA11bde05977b3631167028862bE2a173976CA11", [
      {
        inputs: [{ components: [{ name: "target", type: "address" }, { name: "callData", type: "bytes" }], name: "calls", type: "tuple[]" }],
        name: "aggregate",
        outputs: [{ name: "blockNumber", type: "uint256" }, { name: "returnData", type: "bytes[]" }],
        stateMutability: "payable",
        type: "function"
      }
    ], provider);
  }
  multicall;
  /**
   * Calculate uncollected fees using direct contract simulation or V3 math
   */
  async calculateFees(tokenId, positionData, poolData, owner) {
    if (!poolData || positionData[7].toString() === "0") {
      return { token0UncollectedFees: "0", token1UncollectedFees: "0" };
    }
    try {
      console.log(`\u{1F50D} [V3 FEES] Calculating fees for tokenId ${tokenId}`);
      const collectParams = {
        tokenId,
        recipient: owner,
        // Use actual owner (user or gauge)
        amount0Max: "340282366920938463463374607431768211455",
        // max uint128
        amount1Max: "340282366920938463463374607431768211455"
        // max uint128
      };
      try {
        const simulatedResult = await this.positionManager.callStatic.collect(collectParams, { from: owner });
        console.log(`\u2705 [V3 FEES] Direct collect simulation successful:`, {
          token0: poolData.token0.symbol,
          token1: poolData.token1.symbol,
          token0Fees: simulatedResult.amount0.toString(),
          token1Fees: simulatedResult.amount1.toString()
        });
        return {
          token0UncollectedFees: simulatedResult.amount0.toString(),
          token1UncollectedFees: simulatedResult.amount1.toString()
        };
      } catch (simulationError) {
        console.log(`\u26A0\uFE0F [V3 FEES] Direct simulation failed, using V3 math fallback:`, simulationError);
        return await this.calculateFeesWithV3Math(positionData, poolData);
      }
    } catch (error) {
      console.error("Fee calculation failed:", error);
      return {
        token0UncollectedFees: positionData[10].toString(),
        token1UncollectedFees: positionData[11].toString()
      };
    }
  }
  /**
   * Fallback fee calculation using V3 math
   */
  async calculateFeesWithV3Math(positionData, poolData) {
    try {
      console.log(`\u{1F50D} [V3 FEES] Using V3 math calculation for pool ${poolData.id}`);
      const poolContract = new Contract(poolData.id, [
        {
          inputs: [],
          name: "feeGrowthGlobal0X128",
          outputs: [{ name: "", type: "uint256" }],
          stateMutability: "view",
          type: "function"
        },
        {
          inputs: [],
          name: "feeGrowthGlobal1X128",
          outputs: [{ name: "", type: "uint256" }],
          stateMutability: "view",
          type: "function"
        },
        {
          inputs: [{ name: "tick", type: "int24" }],
          name: "ticks",
          outputs: [
            { name: "liquidityGross", type: "uint128" },
            { name: "liquidityNet", type: "int128" },
            { name: "feeGrowthOutside0X128", type: "uint256" },
            { name: "feeGrowthOutside1X128", type: "uint256" },
            { name: "tickCumulativeOutside", type: "int56" },
            { name: "secondsPerLiquidityOutsideX128", type: "uint160" },
            { name: "secondsOutside", type: "uint32" },
            { name: "initialized", type: "bool" }
          ],
          stateMutability: "view",
          type: "function"
        }
      ], this.provider);
      const calls = [
        {
          target: poolData.id,
          callData: poolContract.interface.encodeFunctionData("feeGrowthGlobal0X128")
        },
        {
          target: poolData.id,
          callData: poolContract.interface.encodeFunctionData("feeGrowthGlobal1X128")
        },
        {
          target: poolData.id,
          callData: poolContract.interface.encodeFunctionData("ticks", [positionData[5]])
          // tickLower
        },
        {
          target: poolData.id,
          callData: poolContract.interface.encodeFunctionData("ticks", [positionData[6]])
          // tickUpper
        }
      ];
      const [, results] = await this.multicall.callStatic.aggregate(calls);
      const feeGrowthGlobal0X128 = poolContract.interface.decodeFunctionResult("feeGrowthGlobal0X128", results[0])[0];
      const feeGrowthGlobal1X128 = poolContract.interface.decodeFunctionResult("feeGrowthGlobal1X128", results[1])[0];
      const tickLowerInfo = poolContract.interface.decodeFunctionResult("ticks", results[2]);
      const tickUpperInfo = poolContract.interface.decodeFunctionResult("ticks", results[3]);
      const feeGrowthOutsideLower = {
        feeGrowthOutside0X128: JSBI.BigInt(tickLowerInfo.feeGrowthOutside0X128.toString()),
        feeGrowthOutside1X128: JSBI.BigInt(tickLowerInfo.feeGrowthOutside1X128.toString())
      };
      const feeGrowthOutsideUpper = {
        feeGrowthOutside0X128: JSBI.BigInt(tickUpperInfo.feeGrowthOutside0X128.toString()),
        feeGrowthOutside1X128: JSBI.BigInt(tickUpperInfo.feeGrowthOutside1X128.toString())
      };
      const [feeGrowthInside0X128, feeGrowthInside1X128] = TickLibrary.getFeeGrowthInside(
        feeGrowthOutsideLower,
        feeGrowthOutsideUpper,
        positionData[5],
        // tickLower
        positionData[6],
        // tickUpper
        parseInt(poolData.tick),
        // tickCurrent
        JSBI.BigInt(feeGrowthGlobal0X128.toString()),
        JSBI.BigInt(feeGrowthGlobal1X128.toString())
      );
      const [tokensOwed0, tokensOwed1] = PositionLibrary.getTokensOwed(
        JSBI.BigInt(positionData[8].toString()),
        // feeGrowthInside0LastX128
        JSBI.BigInt(positionData[9].toString()),
        // feeGrowthInside1LastX128
        JSBI.BigInt(positionData[7].toString()),
        // liquidity
        feeGrowthInside0X128,
        feeGrowthInside1X128
      );
      const finalTokensOwed0 = JSBI.add(tokensOwed0, JSBI.BigInt(positionData[10].toString()));
      const finalTokensOwed1 = JSBI.add(tokensOwed1, JSBI.BigInt(positionData[11].toString()));
      console.log(`\u2705 [V3 FEES] V3 math calculation successful:`, {
        token0Fees: finalTokensOwed0.toString(),
        token1Fees: finalTokensOwed1.toString()
      });
      return {
        token0UncollectedFees: finalTokensOwed0.toString(),
        token1UncollectedFees: finalTokensOwed1.toString()
      };
    } catch (error) {
      console.error("V3 math fee calculation failed:", error);
      return {
        token0UncollectedFees: positionData[10].toString(),
        token1UncollectedFees: positionData[11].toString()
      };
    }
  }
}
