"use strict";
export class V3PoolDataService {
  subgraphUrl = "https://subgraph.satsuma-prod.com/bdd23fa2967b/mss/aborean-finance-v3-abstract-testnet/api";
  /**
   * Fetch pool data by token addresses and tick spacing
   */
  async fetchPoolData(token0, token1, tickSpacing) {
    try {
      const query = `
        query GetPool($token0: String!, $token1: String!) {
          pools(
            where: {
              or: [
                {
                  and: [
                    { token0: $token0 },
                    { token1: $token1 }
                  ]
                },
                {
                  and: [
                    { token0: $token1 },
                    { token1: $token0 }
                  ]
                }
              ]
            }
          ) {
            id
            token0 {
              id
              symbol
              decimals
              name
            }
            token1 {
              id
              symbol
              decimals
              name
            }
            tickSpacing
            liquidity
            sqrtPrice
            tick
            totalValueLockedUSD
          }
        }
      `;
      const response = await fetch(this.subgraphUrl, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          query,
          variables: {
            token0: token0.toLowerCase(),
            token1: token1.toLowerCase()
          }
        })
      });
      const data = await response.json();
      if (data.errors) {
        console.error("Pool query errors:", data.errors);
        return null;
      }
      const pools = data.data?.pools || [];
      const matchingPool = pools.find((pool) => parseInt(pool.tickSpacing) === tickSpacing);
      return matchingPool || null;
    } catch (error) {
      console.error("Failed to fetch pool data:", error);
      return null;
    }
  }
}
