"use strict";
import NonfungiblePositionManagerJson from "@uniswap/v3-periphery/artifacts/contracts/NonfungiblePositionManager.sol/NonfungiblePositionManager.json";
import { getContract } from "utilities/src/contracts/getContract";
const { abi: NFTPositionManagerABI } = NonfungiblePositionManagerJson;
export class NFTOwnershipService {
  constructor(nftManagerAddress, provider) {
    this.nftManagerAddress = nftManagerAddress;
    this.provider = provider;
    this.positionManager = getContract(
      this.nftManagerAddress,
      NFTPositionManagerABI,
      provider
    );
  }
  positionManager;
  /**
   * Check NFT ownership and get position data
   */
  async checkOwnership(tokenId) {
    try {
      let owner;
      try {
        owner = await this.positionManager.ownerOf(tokenId);
      } catch (error) {
        console.error(`\u274C [NFT OWNERSHIP] TokenId ${tokenId} does not exist:`, error);
        return { exists: false };
      }
      const positionData = await this.positionManager.positions(tokenId);
      return {
        exists: true,
        owner,
        positionData
      };
    } catch (error) {
      console.error(`Error checking NFT ownership for ${tokenId}:`, error);
      return { exists: false };
    }
  }
}
